<script lang="ts">
  import {onMount} from 'svelte';import {api,websocketUrl} from '../lib/api.js';import {chooseContext,type WorkbenchState} from '../lib/workbench-state.js';
  import FolderTree from '@lucide/svelte/icons/folder-tree';import Search from '@lucide/svelte/icons/search';import SquareTerminal from '@lucide/svelte/icons/square-terminal';import ChartNoAxesCombined from '@lucide/svelte/icons/chart-no-axes-combined';import Settings from '@lucide/svelte/icons/settings';import ScanSearch from '@lucide/svelte/icons/scan-search';import RefreshCw from '@lucide/svelte/icons/refresh-cw';import Map from '@lucide/svelte/icons/map';import MoreHorizontal from '@lucide/svelte/icons/more-horizontal';import FolderOpen from '@lucide/svelte/icons/folder-open';import Network from '@lucide/svelte/icons/network';
  export let state:WorkbenchState;let contexts:any[]=[];let selected='local';let status='Discovering FNGK…';let repository='/workspace';let activeRail='explorer';let overflow='';const sockets=new Set<WebSocket>();
  async function load(){state.setConnection({phase:'checking',message:'Discovering installed FNGK…'});try{const value=await api<any>('/api/contexts');contexts=value.contexts;selected=chooseContext(contexts,state.snapshot());state.setContext(selected,false);if(value.state.compatible){status=`${value.state.profile??'default'} · ${value.state.version}`;state.setConnection({phase:'connected',message:`Connected to ${value.state.profile??'default'}`,profile:value.state.profile,version:value.state.version});}else{status=value.state.reason??'FNGK unavailable';state.setConnection({phase:value.state.login==='required'?'authentication-required':'unavailable',message:status,profile:value.state.profile,version:value.state.version});}}catch(error){status=(error as Error).message;contexts=[{id:'local',name:'Atlas process host',kind:'local',online:true}];selected='local';state.setContext('local',false);state.setConnection({phase:'unavailable',message:status});}}
  function choose(id:string){selected=id;state.setContext(id);window.dispatchEvent(new CustomEvent('atlas:context',{detail:id}));}
  function scan(){const socket=new WebSocket(websocketUrl(`/api/discovery/scan?contextId=${encodeURIComponent(selected)}`));let failed=false;sockets.add(socket);status='Scanning host…';socket.onmessage=e=>{const v=JSON.parse(e.data);if(v.type==='error'){failed=true;status=v.message??v.code;}state.appendActivity(`${v.type} · ${v.scanned??''}`)};socket.onclose=()=>{sockets.delete(socket);if(!failed){status='Scan complete';window.dispatchEvent(new Event('atlas:graph-refresh'))}}}
  function analyze(){if(!repository.trim())return;const socket=new WebSocket(websocketUrl(`/api/analysis/repository?contextId=${encodeURIComponent(selected)}&path=${encodeURIComponent(repository)}`));let completed=false,failed=false;sockets.add(socket);status='Mapping repository…';socket.onmessage=e=>{const v=JSON.parse(e.data);if(v.type==='error'){failed=true;status=v.message??v.code}state.appendActivity(`${v.type} · ${v.index?.summary?.functions??v.nodes?.length??''}`);if(v.type==='analysis_complete'){completed=true;status=`${v.index.summary.functions} functions mapped`;window.dispatchEvent(new Event('atlas:graph-refresh'))}};socket.onclose=()=>{sockets.delete(socket);if(!completed&&!failed)status='Analysis stopped'}}
  function rail(name:string){activeRail=name;if(name==='terminal')window.dispatchEvent(new Event('atlas:open-terminal'));}
  function action(name:string,id:string){choose(id);overflow='';if(name==='terminal')window.dispatchEvent(new Event('atlas:open-terminal'));if(name==='files')window.dispatchEvent(new Event('atlas:focus-files'));if(name==='scan')scan();if(name==='map')analyze();if(name==='architecture')window.dispatchEvent(new Event('atlas:graph-refresh'));}
  onMount(()=>{void load();void api<any>('/api/contexts').then(value=>{const local=value.contexts?.find((item:any)=>item.id==='local');if(local?.workspaceRoot)repository=local.workspaceRoot}).catch(()=>{});const runScan=()=>scan(),runAnalyze=()=>analyze(),focusSearch=()=>rail('search');window.addEventListener('atlas:scan',runScan);window.addEventListener('atlas:analyze',runAnalyze);window.addEventListener('atlas:focus-search',focusSearch);return()=>{for(const socket of sockets)socket.close();window.removeEventListener('atlas:scan',runScan);window.removeEventListener('atlas:analyze',runAnalyze);window.removeEventListener('atlas:focus-search',focusSearch)}});
</script>

<aside class="navigator"><div class="brand"><img src="/brand/fngk-mark.svg" alt=""/><div><strong>FNGK ATLAS</strong><small>system architecture workbench</small></div><button title="Refresh FNGK namespace" aria-label="Refresh FNGK namespace" onclick={load}><RefreshCw size={14}/></button></div>
{#if activeRail==='explorer'}<div class="section-title">CONTEXTS</div>{#each contexts as item}<div class:active={item.id===selected} class="context-row"><button class="context" onclick={()=>choose(item.id)}><span class:online={item.online}></span><div><b>{item.name}</b><small>{item.kind??'machine'} · {item.online?'reachable':'offline'}</small></div></button><div class="context-actions"><button title="Browse filesystem" aria-label="Browse filesystem" onclick={()=>action('files',item.id)}><FolderOpen size={13}/></button>{#if item.kind==='fngk-device'}<button title="Open attached terminal" aria-label="Open attached terminal" onclick={()=>action('terminal',item.id)}><SquareTerminal size={13}/></button>{/if}<button title="More context actions" aria-label="More context actions" onclick={()=>overflow=overflow===item.id?'':item.id}><MoreHorizontal size={14}/></button>{#if overflow===item.id}<div class="context-overflow"><button onclick={()=>action('architecture',item.id)}><Network size={13}/>Architecture</button><button onclick={()=>action('scan',item.id)}><ScanSearch size={13}/>Scan host</button><button onclick={()=>action('map',item.id)}><Map size={13}/>Map repository</button><button onclick={()=>{choose(item.id);rail('coverage')}}><ChartNoAxesCombined size={13}/>Functions & coverage</button></div>{/if}</div></div>{/each}<div class="section-title repository-title"><span>REPOSITORY PATH</span><button title="Map repository on selected context" aria-label="Map repository" onclick={analyze}><Map size={13}/></button></div><div class="repository"><input bind:value={repository} aria-label="Repository path" placeholder="/path/to/repository"/></div>
{:else if activeRail==='search'}<div class="section-title">SEARCH</div><div class="repository"><input aria-label="Search Atlas" placeholder="Files, symbols, processes…" oninput={(event)=>window.dispatchEvent(new CustomEvent('atlas:search',{detail:(event.currentTarget as HTMLInputElement).value}))}/></div><div class="context-status">Search follows the active context and indexed repository.</div>
{:else if activeRail==='terminal'}<div class="section-title">TERMINALS</div><div class="context-status">The terminal opens attached to the selected online Device and is resizable as a Dockview group.</div>
{:else if activeRail==='coverage'}<div class="section-title">FUNCTIONS & COVERAGE</div><div class="context-status">Open the Functions & coverage Dockview tab for size, complexity, coverage, CRAP, problems, and runs.</div>
{:else}<div class="section-title">SETTINGS</div><div class="context-status">Dock layout is persisted locally. FNGK credentials remain owned by the installed CLI.</div>{/if}
<div class="context-status">{status}</div><div class="navigator-spacer"></div><nav class="rail" aria-label="Atlas views"><button title="Explorer" aria-label="Explorer" class:active={activeRail==='explorer'} onclick={()=>rail('explorer')}><FolderTree size={18}/></button><button title="Search" aria-label="Search" class:active={activeRail==='search'} onclick={()=>rail('search')}><Search size={18}/></button><button title="Terminal" aria-label="Terminal" class:active={activeRail==='terminal'} onclick={()=>rail('terminal')}><SquareTerminal size={18}/></button><button title="Functions and coverage" aria-label="Functions and coverage" class:active={activeRail==='coverage'} onclick={()=>rail('coverage')}><ChartNoAxesCombined size={18}/></button><button title="Settings" aria-label="Settings" class:active={activeRail==='settings'} onclick={()=>rail('settings')}><Settings size={18}/></button></nav></aside>
